import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int m = Integer.parseInt(input[1]);

        List<Integer> primes = new ArrayList<>();
        for (int p = 2; p < 6000; p++) {
            boolean isPrime = true;
            for (int p2 : primes) {
                if (p2 * p2 > p) {
                    break;
                }
                if (p % p2 == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                primes.add(p);
            }
        }

        Map<Long, Map<Long, Integer>> factorCache = new HashMap<>();

        Map<Long, Integer> factor(long n) {
            if (factorCache.containsKey(n)) {
                return factorCache.get(n);
            }
            Map<Long, Integer> d = new HashMap<>();
            long tempN = n;
            for (int p : primes) {
                long pLong = p;
                if (pLong * pLong > tempN) {
                    break;
                }
                if (tempN % pLong == 0) {
                    int c = 0;
                    while (tempN % pLong == 0) {
                        tempN /= pLong;
                        c++;
                    }
                    d.put(pLong, c);
                }
            }
            if (tempN > 1) {
                d.put(tempN, 1);
            }
            factorCache.put(n, d);
            return d;
        }

        List<Long> factors(long n) {
            Map<Long, Integer> d = factor(n);
            List<Long> answer = new ArrayList<>();
            answer.add(1L);
            for (Map.Entry<Long, Integer> entry : d.entrySet()) {
                long p = entry.getKey();
                int exp = entry.getValue();
                List<Long> newAnswer = new ArrayList<>();
                for (Long x : answer) {
                    for (int i = 0; i <= exp; i++) {
                        newAnswer.add(x * pow(p, i));
                    }
                }
                answer = newAnswer;
            }
            return answer;
        }

        long process(int n, int m) {
            Map<Integer, Long> f_dict = new HashMap<>();
            f_dict.put(0, 0L);
            f_dict.put(1, 1L);
            f_dict.put(2, 2L);
            for (int i = 3; i <= n; i++) {
                long val = 2 * f_dict.get(i - 1);
                for (Long x : factors(i)) {
                    if (2 <= x && x <= i) {
                        long term = f_dict.get((int)(i / x)) - f_dict.get((i - 1) / (int)x);
                        val += term;
                        val %= m;
                    }
                }
                val %= m;
                f_dict.put(i, val);
            }
            return f_dict.get(n);
        }

        System.out.println(process(n, m));
    }

    static long pow(long base, int exp) {
        long result = 1;
        for (int i = 0; i < exp; i++) {
            result *= base;
        }
        return result;
    }
}
